import{_ as e,o as t,c as o,a2 as l}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"安装向导","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/install.md","filePath":"deploy/install.md","lastUpdated":1786505997000}'),i={name:"deploy/install.md"};function s(r,a,n,d,c,p){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="安装向导" tabindex="-1">安装向导 <a class="header-anchor" href="#安装向导" aria-label="Permalink to &quot;安装向导&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：首次启动时如何通过 Web 向导完成初始化。</p></blockquote><p>容器启动后，第一次访问会进入<strong>安装向导</strong>（<code>/install</code>）。向导只会在系统未安装时出现，安装完成后不再可访问。</p><h2 id="访问向导" tabindex="-1">访问向导 <a class="header-anchor" href="#访问向导" aria-label="Permalink to &quot;访问向导&quot;">​</a></h2><p>浏览器打开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://服务器IP:端口/install</span></span></code></pre></div><h2 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h2><h3 id="_1-数据库配置" tabindex="-1">1. 数据库配置 <a class="header-anchor" href="#_1-数据库配置" aria-label="Permalink to &quot;1. 数据库配置&quot;">​</a></h3><p>填写你的 PostgreSQL 连接信息，两种方式任选：</p><ul><li><strong>完整 URL</strong>：直接粘贴 <code>postgresql+asyncpg://用户:密码@主机:5432/库名</code>（适合云数据库）。</li><li><strong>分步配置</strong>：分别填主机、端口、库名、用户、密码、是否 SSL。</li></ul><div class="warning custom-block"><p class="custom-block-title">容器内连数据库</p><p>如果数据库在<strong>宿主机</strong>上（不在容器内），主机地址不要填 <code>localhost</code>，要填<strong>宿主机内网 IP</strong> 或 Docker 网关地址（如 <code>172.17.0.1</code>）。云数据库则填 RDS 提供的地址，并确认安全组放行。</p></div><h3 id="_2-redis-配置-可选" tabindex="-1">2. Redis 配置（可选） <a class="header-anchor" href="#_2-redis-配置-可选" aria-label="Permalink to &quot;2. Redis 配置（可选）&quot;">​</a></h3><p>填 Redis 连接地址（默认 <code>redis://localhost:6379/0</code>）。没有 Redis 可留空，系统自动降级为数据库轮询。</p><h3 id="_3-授权码" tabindex="-1">3. 授权码 <a class="header-anchor" href="#_3-授权码" aria-label="Permalink to &quot;3. 授权码&quot;">​</a></h3><p>授权码有两种获取方式，<strong>任选其一</strong>：</p><ul><li><strong>留空 = 自动获取</strong>：系统根据你当前访问的域名，自动向授权云查询并获取授权码。</li><li><strong>手动填写</strong>：如果自动获取失败，直接把开发商发给你的授权码字符串粘贴进来。</li></ul><div class="tip custom-block"><p class="custom-block-title">优先试自动获取</p><p>大多数情况下，只要你的域名已在授权平台登记，留空就能自动获取到。失败时向导会提示，你手动粘贴后重新提交即可。</p></div><h3 id="_4-超级管理员" tabindex="-1">4. 超级管理员 <a class="header-anchor" href="#_4-超级管理员" aria-label="Permalink to &quot;4. 超级管理员&quot;">​</a></h3><p>创建第一个超级管理员账户：用户名、邮箱、QQ 号、密码。</p><p>安装完成后，用这个账户登录 <a href="./../admin/overview">管理后台</a>。</p><h2 id="安装完成" tabindex="-1">安装完成 <a class="header-anchor" href="#安装完成" aria-label="Permalink to &quot;安装完成&quot;">​</a></h2><p>提交后，系统会：</p><ol><li>连接数据库，初始化表结构。</li><li>写入本地配置文件（数据库、Redis、授权码）。</li><li>创建超级管理员、初始化权限、加载平台适配器。</li><li>提示安装成功，跳转到管理员登录页。</li></ol><div class="warning custom-block"><p class="custom-block-title">安装是一次性的</p><p>安装完成后 <code>/install</code> 会被拒绝再次访问。配置写在本地配置文件里，如需修改数据库连接或授权码，编辑该文件后重启容器。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>登录后台开始配置 → <a href="./../admin/overview">管理后台总览</a></li><li>激活授权的细节 → <a href="./authorization">授权激活</a></li></ul>',26)])])}const b=e(i,[["render",s]]);export{u as __pageData,b as default};
